import assert from 'node:assert/strict';
import { MongoClient } from 'mongodb';
const client = new MongoClient(process.env.MONGO_URI);
await client.connect();
const documents = client.db().collection('documents');
if (process.argv[2] === 'readback') {
  const kept = await documents.find({}).sort({ a: 1 }).toArray();
  assert.deepEqual(kept.map(({ a, b }) => ({ a, b })), [{ a: 1, b: undefined }, { a: 2, b: undefined }, { a: 3, b: 1 }]);
  assert.equal((await documents.indexes()).some((index) => index.name === 'a_1'), true);
  console.log(JSON.stringify({ retained: true, documents: kept.length }));
} else {
  const inserted = await documents.insertMany([{ a: 1 }, { a: 2 }, { a: 3 }, { a: 4 }]);
  assert.equal(inserted.insertedCount, 4);
  assert.deepEqual((await documents.find({ a: 3 }).toArray()).map(({ a }) => a), [3]);
  const updated = await documents.updateOne({ a: 3 }, { $set: { b: 1 } });
  assert.equal(updated.matchedCount, 1);
  assert.equal(updated.modifiedCount, 1);
  const deleted = await documents.deleteMany({ a: 4 });
  assert.equal(deleted.deletedCount, 1);
  assert.equal(await documents.createIndex({ a: 1 }), 'a_1');
  assert.equal((await documents.find({}).toArray()).length, 3);
  console.log(JSON.stringify({ inserted: inserted.insertedCount, updated: updated.modifiedCount, deleted: deleted.deletedCount, index: 'a_1' }));
}
await client.close();
